import { getDb, kvGet, kvSet } from "./db";

/**
 * Historical exchange rates for showing dollar figures in CZK or EUR.
 *
 * The source is the Czech National Bank's daily fixing: free, no key, back to
 * 1991, and one file per year with every currency against CZK. USD→EUR is
 * derived from the two CZK rates, the same way the CNB's own cross rates are.
 * Rates are stored in `fx_rates`, so a past year is downloaded once and the
 * current one at most every few hours.
 */

export type Currency = "USD" | "CZK" | "EUR";
export const CURRENCIES: Currency[] = ["USD", "CZK", "EUR"];

const CNB_YEAR_URL =
  "https://www.cnb.cz/cs/financni-trhy/devizovy-trh/kurzy-devizoveho-trhu/kurzy-devizoveho-trhu/rok.txt?rok=";

/** The running year is re-fetched after this long; the CNB publishes once a day. */
const CURRENT_YEAR_TTL_MS = 6 * 3_600_000;

/** Codes kept from the CNB file — the only two the app converts through. */
const WANTED = ["USD", "EUR"] as const;

/**
 * Parse one yearly CNB file into CZK-per-unit rates.
 *
 * The header can repeat mid-year when the list of currencies changes (the
 * kuna left in 2023), so column positions are re-read at every "Datum" line.
 * Amounts like "100 JPY" are divided back to one unit.
 */
export function parseCnbYear(text: string): { currency: string; date: string; czk: number }[] {
  const out: { currency: string; date: string; czk: number }[] = [];
  let cols: { code: string; index: number; amount: number }[] = [];
  for (const line of text.split(/\r?\n/)) {
    if (!line.trim()) continue;
    const cells = line.split("|");
    if (cells[0] === "Datum") {
      cols = [];
      cells.forEach((h, i) => {
        const m = h.trim().match(/^(\d+)\s+([A-Z]{3})$/);
        if (m && (WANTED as readonly string[]).includes(m[2])) {
          cols.push({ code: m[2], index: i, amount: Number(m[1]) });
        }
      });
      continue;
    }
    const d = cells[0].match(/^(\d{2})\.(\d{2})\.(\d{4})$/);
    if (!d) continue;
    const date = `${d[3]}-${d[2]}-${d[1]}`;
    for (const c of cols) {
      const rate = Number((cells[c.index] ?? "").replace(",", "."));
      if (Number.isFinite(rate) && rate > 0) out.push({ currency: c.code, date, czk: rate / c.amount });
    }
  }
  return out;
}

async function fetchYear(year: number): Promise<void> {
  const res = await fetch(CNB_YEAR_URL + year, {
    cache: "no-store",
    signal: AbortSignal.timeout(20_000),
  });
  if (!res.ok) throw new Error(`ČNB vrátila HTTP ${res.status}`);
  const rows = parseCnbYear(await res.text());
  if (rows.length === 0) throw new Error(`V kurzech ČNB za rok ${year} nejsou USD ani EUR`);

  const db = getDb();
  const stmt = db.prepare(
    `INSERT INTO fx_rates (currency, date, czk) VALUES (?,?,?)
     ON CONFLICT(currency, date) DO UPDATE SET czk = excluded.czk`,
  );
  db.transaction(() => {
    for (const r of rows) stmt.run(r.currency, r.date, r.czk);
  })();
  kvSet(`fx:cnb:${year}`, String(rows.length));
}

/** Make sure every year from `fromYear` to now is stored; returns what failed. */
async function ensureYears(fromYear: number): Promise<string[]> {
  const nowYear = new Date().getFullYear();
  const errors: string[] = [];
  for (let y = Math.max(1991, fromYear); y <= nowYear; y++) {
    const fresh = kvGet(`fx:cnb:${y}`, y === nowYear ? CURRENT_YEAR_TTL_MS : undefined);
    if (fresh !== null) continue;
    try {
      await fetchYear(y);
    } catch (e) {
      errors.push(`${y}: ${(e as Error).message}`);
    }
  }
  return errors;
}

type Rate = { date: string; czk: number };

function loadRates(currency: string): Rate[] {
  return getDb()
    .prepare(`SELECT date, czk FROM fx_rates WHERE currency = ? ORDER BY date`)
    .all(currency) as Rate[];
}

/**
 * Rate in force on `date`: the last fixing on or before it (weekends and
 * holidays carry Friday's), or the first one when the date is older still.
 */
function lookup(rates: Rate[]): (date: string) => number {
  return (date: string) => {
    let lo = 0;
    let hi = rates.length - 1;
    let hit = 0;
    while (lo <= hi) {
      const mid = (lo + hi) >> 1;
      if (rates[mid].date <= date) {
        hit = mid;
        lo = mid + 1;
      } else hi = mid - 1;
    }
    return rates[hit].czk;
  };
}

export type Converter = {
  /** The currency the figures actually come out in — USD if rates were unavailable. */
  currency: Currency;
  /** Multiplier from US dollars on `date` into `currency`. */
  fromUsd: (date: string) => number;
  /** Newest stored fixing, so the page can say how current the rate is. */
  ratesAsOf: string | null;
  warning: string | null;
};

const IDENTITY: Converter = { currency: "USD", fromUsd: () => 1, ratesAsOf: null, warning: null };

/**
 * A USD → `currency` converter covering every date from `fromDate` on.
 *
 * Falls back to plain dollars, with a warning, when the rates cannot be had —
 * a figure in the wrong currency labelled as such beats no figure at all.
 */
export async function converter(currency: Currency, fromDate: string | null): Promise<Converter> {
  if (currency === "USD") return IDENTITY;

  const errors = await ensureYears(Number((fromDate ?? new Date().toISOString()).slice(0, 4)));
  const usd = loadRates("USD");
  const eur = loadRates("EUR");
  const needed = currency === "CZK" ? [usd] : [usd, eur];
  if (needed.some((r) => r.length === 0)) {
    return {
      ...IDENTITY,
      warning: `Kurzy ČNB se nepodařilo stáhnout (${errors.join("; ") || "žádná data"}), částky jsou proto v USD.`,
    };
  }

  const usdCzk = lookup(usd);
  const eurCzk = lookup(eur);
  const newest = needed.map((r) => r[r.length - 1].date).sort()[0];
  const firstYear = fromDate?.slice(0, 4);
  const coverageGap = firstYear && usd[0].date.slice(0, 4) > firstYear;

  return {
    currency,
    fromUsd: currency === "CZK" ? usdCzk : (date) => usdCzk(date) / eurCzk(date),
    ratesAsOf: newest,
    warning:
      errors.length > 0 || coverageGap
        ? `Některé roky kurzů ČNB chybí (${errors.join("; ") || "starší data"}); pro chybějící dny se použije nejbližší známý kurz.`
        : null,
  };
}

export function asCurrency(value: unknown): Currency {
  return typeof value === "string" && (CURRENCIES as string[]).includes(value) ? (value as Currency) : "USD";
}
