import { getDb } from "./db";
import { getSplits, splitFactorLookup } from "./prices";
import {
  SPY_TICKER,
  barAsOf,
  barAtOrAfter,
  loadBars,
  loadDividends,
  type Bar,
} from "./portfolio";
import type { SeriesPoint } from "./types";

/**
 * Monitoring of the real portfolio.
 *
 * The input is a journal of buys — every top-up is its own row, so one ticker
 * can be there ten times. Out of it come the holdings per ticker, how the
 * capital splits across stocks, sectors and sub-sectors, and a benchmark: on
 * the day of every buy the same money virtually buys SPY, and the two piles of
 * profit are followed side by side.
 *
 * Everything is computed in US dollars and converted on the way out, each
 * amount at the rate of its own day: a buy at the rate of the buy date, a
 * dividend at the rate of its payment, today's value at today's. A profit in
 * CZK therefore includes what the dollar itself did, which is exactly what a
 * Czech holder gains or loses. The benchmark buys SPY with the same dollars.
 *
 * Profit on both sides is price gain plus dividends received as cash (gross,
 * not reinvested). Leaving dividends out would stack the comparison against
 * dividend payers, since SPY's own payout would be missing just the same.
 */

/** A sector holding more than this share of the capital raises a warning. */
export const SECTOR_LIMIT_PCT = 50;

/** The donut shows this many slices; the rest folds into "Ostatní". */
const MAX_SLICES = 7;

const UNCLASSIFIED = "Nezařazeno";

/* ------------------------------------------------------------------ */
/* journal                                                             */
/* ------------------------------------------------------------------ */

export type Trade = {
  id: number;
  ticker: string;
  shares: number;
  buyDate: string;
  /** Null means the close of the buy date is taken as the price paid. */
  buyPrice: number | null;
  note: string | null;
};

export type TradeInput = {
  ticker: string;
  shares: number;
  buyDate: string;
  buyPrice?: number | null;
  note?: string | null;
};

type TradeRow = {
  id: number;
  ticker: string;
  shares: number;
  buy_date: string;
  buy_price: number | null;
  note: string | null;
};

const toTrade = (r: TradeRow): Trade => ({
  id: r.id,
  ticker: r.ticker,
  shares: r.shares,
  buyDate: r.buy_date,
  buyPrice: r.buy_price,
  note: r.note,
});

export function listTrades(): Trade[] {
  const rows = getDb()
    .prepare(
      `SELECT id, ticker, shares, buy_date, buy_price, note
       FROM trades ORDER BY buy_date, ticker, id`,
    )
    .all() as TradeRow[];
  return rows.map(toTrade);
}

export function addTrade(input: TradeInput): void {
  getDb()
    .prepare(
      `INSERT INTO trades (ticker, shares, buy_date, buy_price, note, created_at)
       VALUES (?,?,?,?,?,?)`,
    )
    .run(
      input.ticker,
      input.shares,
      input.buyDate,
      input.buyPrice ?? null,
      input.note ?? null,
      new Date().toISOString(),
    );
}

export function updateTrade(id: number, input: TradeInput): boolean {
  return (
    getDb()
      .prepare(
        `UPDATE trades SET ticker = ?, shares = ?, buy_date = ?, buy_price = ?, note = ?
         WHERE id = ?`,
      )
      .run(
        input.ticker,
        input.shares,
        input.buyDate,
        input.buyPrice ?? null,
        input.note ?? null,
        id,
      ).changes > 0
  );
}

export function deleteTrade(id: number): boolean {
  return getDb().prepare(`DELETE FROM trades WHERE id = ?`).run(id).changes > 0;
}

/* ------------------------------------------------------------------ */
/* result types                                                        */
/* ------------------------------------------------------------------ */

export type TradeResult = Trade & {
  /** Price actually used as the cost basis — entered, or the close of the day. */
  price: number | null;
  cost: number | null;
  /** Shares today, after every split since the buy. */
  sharesNow: number;
  value: number | null;
  dividends: number;
  profit: number | null;
  /** What the same money in SPY on the same day would have made. */
  spyProfit: number | null;
  /** Why this buy is left out of every figure, when it is. */
  problem: string | null;
};

export type Holding = {
  ticker: string;
  name: string | null;
  sector: string | null;
  subIndustry: string | null;
  /** "index" = GICS from the index list, "sic" = derived from SEC's SIC. */
  sectorSource: string | null;
  buys: number;
  firstBuy: string;
  sharesNow: number;
  cost: number;
  /** Cost per share held today, i.e. already restated for splits. */
  avgPrice: number;
  lastPrice: number;
  lastDate: string;
  value: number;
  priceGain: number;
  dividends: number;
  profit: number;
  profitPct: number;
  /** Share of the portfolio's current value, in percent. */
  weight: number;
  spyProfit: number | null;
  /** Profit minus what SPY would have made — above zero, the pick beat the index. */
  vsSpy: number | null;
};

export type Slice = {
  key: string;
  label: string;
  value: number;
  weight: number;
  /** Categorical slot 1–7, fixed by first purchase; 0 = folded "Ostatní". */
  slot: number;
  /** Tickers inside, so a sector slice can say what it is made of. */
  tickers: string[];
};

export type Allocation = { slices: Slice[]; all: Slice[] };

export type MonitoringSummary = {
  firstDate: string | null;
  /** Oldest "last price" among the holdings — how fresh the whole picture is. */
  pricesAsOf: string | null;
  invested: number;
  value: number;
  priceGain: number;
  dividends: number;
  profit: number;
  profitPct: number | null;
  spyInvested: number;
  spyProfit: number | null;
  spyProfitPct: number | null;
};

export type Monitoring = {
  trades: TradeResult[];
  holdings: Holding[];
  allocation: { stocks: Allocation; sectors: Allocation; subIndustries: Allocation };
  /** Sectors above SECTOR_LIMIT_PCT, largest first. */
  concentration: { sector: string; weight: number; tickers: string[] }[];
  sectorLimit: number;
  timeline: Record<string, SeriesPoint[]>;
  summary: MonitoringSummary;
  /** Tickers the journal holds that are not downloaded at all. */
  missing: string[];
  /** Everything held (plus SPY) — what "Aktualizovat ceny" should top up. */
  priceTickers: string[];
  warnings: string[];
};

/* ------------------------------------------------------------------ */
/* computation                                                         */
/* ------------------------------------------------------------------ */

type CompanyRow = {
  ticker: string;
  name: string | null;
  sector: string | null;
  sub_industry: string | null;
  sector_source: string | null;
};

function loadCompanies(tickers: string[]): Map<string, CompanyRow> {
  const out = new Map<string, CompanyRow>();
  if (tickers.length === 0) return out;
  const rows = getDb()
    .prepare(
      `SELECT ticker, name, sector, sub_industry, sector_source FROM companies
       WHERE ticker IN (${tickers.map(() => "?").join(",")})`,
    )
    .all(...tickers) as CompanyRow[];
  for (const r of rows) out.set(r.ticker, r);
  return out;
}

type Series = { bars: Bar[]; factor: (date: string) => number };

function loadSeries(ticker: string): Series {
  return { bars: loadBars(ticker), factor: splitFactorLookup(getSplits(ticker)) };
}

/** A buy the calculation can actually run, with everything precomputed. */
type Active = {
  trade: Trade;
  /** Price and cost in the display currency, at the rate of the buy date. */
  price: number;
  cost: number;
  /** Cost in dollars — what buys the matching SPY. */
  costUsd: number;
  /** Shares held on `date`, restated through every split since the buy. */
  sharesAt: (date: string) => number;
  /** SPY bought on the same day for the same money; 0 without SPY prices. */
  spyShares: number;
};

/**
 * `fx` turns a dollar amount on a given date into the display currency;
 * the default keeps everything in dollars.
 */
export function monitor(trades: Trade[], fx: (date: string) => number = () => 1): Monitoring {
  const warnings: string[] = [];
  const tickers = [...new Set(trades.map((t) => t.ticker))];
  const companies = loadCompanies([...tickers, SPY_TICKER]);

  const series = new Map<string, Series>();
  for (const t of [...tickers, SPY_TICKER]) series.set(t, loadSeries(t));
  const spy = series.get(SPY_TICKER)!;
  const spyLast = spy.bars[spy.bars.length - 1] ?? null;

  const missing = tickers.filter((t) => !companies.has(t));
  const priceTickers = [...tickers.filter((t) => companies.has(t)), SPY_TICKER];

  if (trades.length > 0 && spy.bars.length === 0) {
    warnings.push(
      `${SPY_TICKER} nemá v databázi ceny, takže není s čím srovnávat. Stáhni ho tlačítkem u srovnání nebo v záložce „Data a stahování“.`,
    );
  }

  /* ---- which buys can be valued ---- */

  const results: TradeResult[] = [];
  const active: Active[] = [];
  let spyTooLate = 0;

  for (const trade of trades) {
    const { bars, factor } = series.get(trade.ticker)!;
    const sharesAt = (date: string) =>
      trade.shares * (factor(trade.buyDate) / factor(date));
    const last = bars[bars.length - 1];
    const base: TradeResult = {
      ...trade,
      price: trade.buyPrice,
      cost: trade.buyPrice !== null ? trade.buyPrice * trade.shares : null,
      sharesNow: last ? sharesAt(last.date) : trade.shares,
      value: null,
      dividends: 0,
      profit: null,
      spyProfit: null,
      problem: null,
    };

    if (!companies.has(trade.ticker)) {
      results.push({ ...base, problem: "ticker není stažený" });
      continue;
    }
    if (!last) {
      results.push({ ...base, problem: "žádné stažené ceny" });
      warnings.push(`${trade.ticker} nemá stažené ceny — nákup se nezapočítá.`);
      continue;
    }
    if (trade.buyDate > last.date) {
      results.push({ ...base, problem: `ceny končí ${last.date}` });
      warnings.push(
        `${trade.ticker}: ceny končí ${last.date}, nákup ${trade.buyDate} je novější — nezapočítá se, dokud ceny nedoplníš.`,
      );
      continue;
    }

    const atBuy = barAsOf(bars, trade.buyDate) ?? bars[0];
    const priceUsd = trade.buyPrice ?? atBuy.close;
    const costUsd = priceUsd * trade.shares;
    const rate = fx(trade.buyDate);
    const price = priceUsd * rate;
    const cost = costUsd * rate;

    // Same day, same money. Weekly bars mean "the close of that week" — the
    // stock's own fallback price uses exactly the same rule.
    const spyBar =
      spyLast && trade.buyDate <= spyLast.date
        ? (barAsOf(spy.bars, trade.buyDate) ?? barAtOrAfter(spy.bars, trade.buyDate))
        : null;
    if (spy.bars.length > 0 && !spyBar) spyTooLate++;

    active.push({
      trade,
      price,
      cost,
      costUsd,
      sharesAt,
      spyShares: spyBar ? costUsd / spyBar.close : 0,
    });
    results.push({ ...base, price, cost });
  }

  if (spyTooLate > 0 && spyLast) {
    warnings.push(
      `Ceny SPY končí ${spyLast.date}; ${spyTooLate === 1 ? "jeden nákup je" : `${spyTooLate} nákupy jsou`} novější, takže se do srovnání s indexem nepromítnou. Aktualizuj ceny.`,
    );
  }

  /* ---- dividends as cash events, stock side and SPY side ---- */

  type Payout = { date: string; stock: number; spy: number; trade: number };
  const payouts: Payout[] = [];
  const dividendCache = new Map<string, { date: string; amount: number }[]>();
  const dividendsOf = (t: string) => {
    let d = dividendCache.get(t);
    if (!d) dividendCache.set(t, (d = loadDividends(t)));
    return d;
  };

  active.forEach((a, i) => {
    // A payment on the buy date or before it is out of the buyer's reach.
    for (const d of dividendsOf(a.trade.ticker)) {
      if (d.date <= a.trade.buyDate) continue;
      const cash = a.sharesAt(d.date) * d.amount * fx(d.date);
      if (Number.isFinite(cash) && cash > 0) payouts.push({ date: d.date, stock: cash, spy: 0, trade: i });
    }
    if (a.spyShares > 0) {
      for (const d of dividendsOf(SPY_TICKER)) {
        if (d.date <= a.trade.buyDate) continue;
        const shares = a.spyShares * (spy.factor(a.trade.buyDate) / spy.factor(d.date));
        const cash = shares * d.amount * fx(d.date);
        if (Number.isFinite(cash) && cash > 0) payouts.push({ date: d.date, stock: 0, spy: cash, trade: i });
      }
    }
  });
  payouts.sort((a, b) => a.date.localeCompare(b.date));

  const stockDivByTrade = new Array<number>(active.length).fill(0);
  const spyDivByTrade = new Array<number>(active.length).fill(0);
  for (const p of payouts) {
    stockDivByTrade[p.trade] += p.stock;
    spyDivByTrade[p.trade] += p.spy;
  }

  /* ---- per-buy results ---- */

  const spyValueNow = (a: Active) =>
    spyLast
      ? a.spyShares *
        (spy.factor(a.trade.buyDate) / spy.factor(spyLast.date)) *
        spyLast.close *
        fx(spyLast.date)
      : 0;

  active.forEach((a, i) => {
    const { bars } = series.get(a.trade.ticker)!;
    const last = bars[bars.length - 1];
    const value = a.sharesAt(last.date) * last.close * fx(last.date);
    const r = results.find((x) => x.id === a.trade.id)!;
    r.value = value;
    r.dividends = stockDivByTrade[i];
    r.profit = value + stockDivByTrade[i] - a.cost;
    r.spyProfit = a.spyShares > 0 ? spyValueNow(a) + spyDivByTrade[i] - a.cost : null;
  });

  /* ---- holdings per ticker ---- */

  const byTicker = new Map<string, { active: Active[]; idx: number[] }>();
  active.forEach((a, i) => {
    const g = byTicker.get(a.trade.ticker) ?? { active: [], idx: [] };
    g.active.push(a);
    g.idx.push(i);
    byTicker.set(a.trade.ticker, g);
  });

  const holdings: Holding[] = [];
  for (const [ticker, g] of byTicker) {
    const { bars } = series.get(ticker)!;
    const last = bars[bars.length - 1];
    const company = companies.get(ticker)!;
    const sharesNow = g.active.reduce((s, a) => s + a.sharesAt(last.date), 0);
    const cost = g.active.reduce((s, a) => s + a.cost, 0);
    const lastPrice = last.close * fx(last.date);
    const value = sharesNow * lastPrice;
    const dividends = g.idx.reduce((s, i) => s + stockDivByTrade[i], 0);
    const profit = value + dividends - cost;
    // Only buys that could be benchmarked; a partial SPY figure would mislead.
    const benchmarked = g.active.every((a) => a.spyShares > 0);
    const spyProfit = benchmarked
      ? g.active.reduce((s, a, k) => s + spyValueNow(a) + spyDivByTrade[g.idx[k]] - a.cost, 0)
      : null;

    holdings.push({
      ticker,
      name: company.name,
      sector: company.sector,
      subIndustry: company.sub_industry,
      sectorSource: company.sector_source,
      buys: g.active.length,
      firstBuy: g.active[0].trade.buyDate,
      sharesNow,
      cost,
      avgPrice: sharesNow > 0 ? cost / sharesNow : 0,
      lastPrice,
      lastDate: last.date,
      value,
      priceGain: value - cost,
      dividends,
      profit,
      profitPct: cost > 0 ? (profit / cost) * 100 : 0,
      weight: 0,
      spyProfit,
      vsSpy: spyProfit !== null ? profit - spyProfit : null,
    });
  }

  const totalValue = holdings.reduce((s, h) => s + h.value, 0);
  for (const h of holdings) h.weight = totalValue > 0 ? (h.value / totalValue) * 100 : 0;
  holdings.sort((a, b) => b.value - a.value);

  /* ---- allocation ---- */

  const allocate = (keyOf: (h: Holding) => string | null): Allocation => {
    const groups = new Map<string, Slice & { first: string }>();
    for (const h of holdings) {
      const key = keyOf(h) ?? UNCLASSIFIED;
      const g = groups.get(key) ?? {
        key,
        label: key,
        value: 0,
        weight: 0,
        slot: 0,
        tickers: [],
        first: h.firstBuy,
      };
      g.value += h.value;
      g.tickers.push(h.ticker);
      if (h.firstBuy < g.first) g.first = h.firstBuy;
      groups.set(key, g);
    }
    const all = [...groups.values()].sort((a, b) => b.value - a.value);
    for (const g of all) g.weight = totalValue > 0 ? (g.value / totalValue) * 100 : 0;

    // Eight slices fit the palette exactly; past that, the top seven stay and
    // the rest folds, so "Ostatní" never needs a ninth colour.
    const shown = all.length > MAX_SLICES + 1 ? all.slice(0, MAX_SLICES) : all;
    // Slots follow the first purchase, so a price move that swaps two slices'
    // sizes never repaints them.
    [...shown]
      .sort((a, b) => a.first.localeCompare(b.first) || b.value - a.value)
      .forEach((g, i) => (g.slot = i + 1));

    const strip = ({ first: _first, ...slice }: Slice & { first: string }): Slice => slice;
    const slices = shown.map(strip);
    const rest = all.slice(shown.length);
    if (rest.length > 0) {
      const value = rest.reduce((s, g) => s + g.value, 0);
      slices.push({
        key: "__ostatni",
        label: `Ostatní (${rest.length})`,
        value,
        weight: totalValue > 0 ? (value / totalValue) * 100 : 0,
        slot: 0,
        tickers: rest.flatMap((g) => g.tickers),
      });
    }
    return { slices, all: all.map(strip) };
  };

  const allocation = {
    stocks: allocate((h) => h.ticker),
    sectors: allocate((h) => h.sector),
    subIndustries: allocate((h) => h.subIndustry),
  };

  const concentration = allocation.sectors.all
    .filter((s) => s.key !== UNCLASSIFIED && s.weight > SECTOR_LIMIT_PCT)
    .map((s) => ({ sector: s.label, weight: s.weight, tickers: s.tickers }));

  const unclassified = holdings.filter((h) => !h.sector).map((h) => h.ticker);
  if (unclassified.length > 0) {
    warnings.push(
      `Bez sektoru: ${unclassified.join(", ")} — v koláči sektorů jsou jako „${UNCLASSIFIED}“ (typicky ETF, které u SEC nemají klasifikaci).`,
    );
  }

  /* ---- timeline: profit of the picks vs the same money in SPY ---- */

  const timeline: Record<string, SeriesPoint[]> = { profit: [], spyProfit: [] };
  if (active.length > 0) {
    const start = active.reduce((m, a) => (a.trade.buyDate < m ? a.trade.buyDate : m), active[0].trade.buyDate);
    const grid = new Set<string>([start]);
    for (const t of new Set(active.map((a) => a.trade.ticker))) {
      for (const b of series.get(t)!.bars) if (b.date >= start) grid.add(b.date);
    }
    const lastStockDate = holdings.reduce((m, h) => (h.lastDate > m ? h.lastDate : m), start);
    for (const b of spy.bars) if (b.date >= start && b.date <= lastStockDate) grid.add(b.date);
    const dates = [...grid].sort();
    const hasSpy = active.some((a) => a.spyShares > 0);

    let cursor = 0;
    let stockCash = 0;
    let spyCash = 0;
    for (const date of dates) {
      while (cursor < payouts.length && payouts[cursor].date <= date) {
        stockCash += payouts[cursor].stock;
        spyCash += payouts[cursor].spy;
        cursor++;
      }
      let stockValue = 0;
      let spyValue = 0;
      let cost = 0;
      let spyCost = 0;
      const spyBar = barAsOf(spy.bars, date);
      const rate = fx(date);
      for (const a of active) {
        if (a.trade.buyDate > date) continue;
        const bar = barAsOf(series.get(a.trade.ticker)!.bars, date);
        // Bought before the stored history begins: value it at the entry price.
        stockValue += bar ? a.sharesAt(date) * bar.close * rate : a.cost;
        cost += a.cost;
        if (a.spyShares > 0) {
          spyValue += spyBar
            ? a.spyShares * (spy.factor(a.trade.buyDate) / spy.factor(date)) * spyBar.close * rate
            : a.cost;
          spyCost += a.cost;
        }
      }
      timeline.profit.push({ date, value: stockValue + stockCash - cost });
      if (hasSpy) timeline.spyProfit.push({ date, value: spyValue + spyCash - spyCost });
    }
  }

  /* ---- summary ---- */

  const invested = holdings.reduce((s, h) => s + h.cost, 0);
  const dividends = holdings.reduce((s, h) => s + h.dividends, 0);
  const profit = totalValue + dividends - invested;
  const benchmarked = active.filter((a) => a.spyShares > 0);
  const spyInvested = benchmarked.reduce((s, a) => s + a.cost, 0);
  const spyProfit =
    benchmarked.length > 0
      ? active.reduce(
          (s, a, i) => (a.spyShares > 0 ? s + spyValueNow(a) + spyDivByTrade[i] - a.cost : s),
          0,
        )
      : null;

  return {
    trades: results,
    holdings,
    allocation,
    concentration,
    sectorLimit: SECTOR_LIMIT_PCT,
    timeline,
    summary: {
      firstDate: active.length
        ? active.reduce((m, a) => (a.trade.buyDate < m ? a.trade.buyDate : m), active[0].trade.buyDate)
        : null,
      pricesAsOf: holdings.length
        ? holdings.reduce((m, h) => (h.lastDate < m ? h.lastDate : m), holdings[0].lastDate)
        : null,
      invested,
      value: totalValue,
      priceGain: totalValue - invested,
      dividends,
      profit,
      profitPct: invested > 0 ? (profit / invested) * 100 : null,
      spyInvested,
      spyProfit,
      spyProfitPct: spyProfit !== null && spyInvested > 0 ? (spyProfit / spyInvested) * 100 : null,
    },
    missing,
    priceTickers,
    warnings,
  };
}
